/**
 * @method
 * @name scwin.makeTitleOfAccountParamString
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.makeTitleOfAccountParamString = function () {
    /* sdd-asis-lifecycle:begin makeTitleOfAccountParamString — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var paramString = "";
    const id = "";
    let flag = false;
    var paramString = "";
    const finstat = new Array("A010", "A040", "A080", "A090", "A100", "A110", "A120", "A130", "A140", "A160", "A170", "A180", "A190", "A200");
    for (let i = 0; i < finstat.length; i++) {
        flag = scwin.checkChkBoxStatus(finstat[i]);
        if (flag) {
            paramString += finstat[i];
            if (i !== (finstat.length - 1)) {
                paramString += "|";
            }
        }
    }
    return paramString;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkChkBoxStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.checkChkBoxStatus = function (id) {
    /* sdd-asis-lifecycle:begin checkChkBoxStatus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return $("#" + id).is(":checked");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const searchForm = $("#searchForm");
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    if (scwin.checkValidationOfAccountValue() === false) {
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_range");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_range");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkValidationOfAccountValue
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkValidationOfAccountValue = function () {
    /* sdd-asis-lifecycle:begin checkValidationOfAccountValue — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (compareTwoValueOfAccnt("'유동자산'", $("#ipt_a010From"), $("#ipt_a010To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'고정자산'", $("#ipt_a040From"), $("#ipt_a040To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'자산총계'", $("#ipt_a080From"), $("#ipt_a080To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'유동부채'", $("#ipt_a090From"), $("#ipt_a090To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'고정부채'", $("#ipt_a100From"), $("#ipt_a100To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'부채총계'", $("#ipt_a110From"), $("#ipt_a110To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'자본금'", $("#ipt_a120From"), $("#ipt_a120To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'자본잉여금'", $("#ipt_a130From"), $("#ipt_a130To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'이익잉여금'", $("#ipt_a140From"), $("#ipt_a140To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'자본총계'", $("#ipt_a160From"), $("#ipt_a160To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'매출액(수익)'", $("#ipt_a170From"), $("#ipt_a170To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'영업이익'", $("#ipt_a180From"), $("#ipt_a180To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'법인세차감전계속사업이익'", $("#ipt_a190From"), $("#ipt_a190To")) === false) {
        return false;
    }
    if (compareTwoValueOfAccnt("'당기순이익'", $("#ipt_a200From"), $("#ipt_a200To")) === false) {
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
